const jewelryOptions={en:{origin:'Diamond origin',colors:'Diamond color',metals:'Gold color',lab:'Lab-grown',natural:'Natural',diamond:[['white','White'],['pink','Pink'],['yellow','Yellow'],['blue','Blue'],['other','Other']],gold:[['yellow','Yellow gold'],['white','White gold'],['rose','Rose gold']],hint:'Select your preferences. Every combination is subject to stone availability, design feasibility, and an individual quote.'},ko:{origin:'다이아몬드 종류',colors:'다이아몬드 색상',metals:'골드 색상',lab:'랩그로운',natural:'천연',diamond:[['white','화이트'],['pink','핑크'],['yellow','옐로'],['blue','블루'],['other','기타']],gold:[['yellow','옐로 골드'],['white','화이트 골드'],['rose','로즈 골드']],hint:'원하시는 조합을 선택해 주세요. 실제 제작 가능 여부와 최종 가격은 보석 수급, 디자인 검토 후 개별적으로 안내합니다.'}};
function choiceGroup(name,label,options,id,selected){return `<fieldset class="diamond-choice"><legend>${label}</legend><div class="stone-options">${options.map(([value,title])=>`<label class="stone-choice"><input type="radio" name="${name}-${id}" value="${value}" ${value===selected?'checked':''}><span>${title}</span></label>`).join('')}</div></fieldset>`}
function catalogDetails(spec,id){const t=catalogLabels[lang],o=jewelryOptions[lang];const rows=[['diamond',spec.total],['center',spec.center],['melee',spec.melee],['pieces',spec.pieces],['goldWeight',spec.goldWeight]].filter(([,value])=>value!==undefined).map(([key,value])=>`<li><span>${t[key]}</span><strong>${value}</strong></li>`).join('');return `<div class="catalog-details"><p class="catalog-price">${spec.price?`${t.starts} USD ${spec.price.toLocaleString('en-US')}`:t.request}</p><p class="catalog-metal">${spec.gold} ${t.gold}</p>${rows?`<ul>${rows}</ul>`:`<p class="spec-pending">${lang==='ko'?'캐럿·골드 중량은 개별 문의 시 안내합니다.':'Carat and gold weights are confirmed on inquiry.'}</p>`}<div class="jewelry-choices">${choiceGroup('diamond-origin',o.origin,[['lab-grown',o.lab],['natural',o.natural]],id,'lab-grown')}${choiceGroup('diamond-color',o.colors,o.diamond,id,picturedColor[Number(id.split('-')[1])])}${choiceGroup('gold-color',o.metals,[['pictured',lang==='ko'?'사진 속 구성':'As photographed'],...o.gold],id,picturedGold[Number(id.split('-')[1])])}<p class="choice-hint">${o.hint}</p><p class="natural-premium" id="natural-premium-${id}" hidden>${lang==='ko'?'천연 다이아몬드는 추가 비용이 발생합니다. 정확한 가격은 문의해 주세요.':'Natural diamonds incur an additional cost. Please inquire for an individual quote.'}</p></div></div>`}
