const productPageCopy={en:{back:'Back to the collection',view:'View piece',discuss:'Discuss this piece',details:'The piece',origin:'Select your preferred diamond',note:'Editorial visualization. Specifications and starting prices are approximate; the final proposal depends on the chosen diamonds and details.',moreDescriptions:['A flowing sequence of pear-shaped diamonds in yellow gold.','A radiant-cut center framed by a halo of diamonds.','A round center framed by a halo of diamonds.']},ko:{back:'컬렉션으로 돌아가기',view:'작품 자세히 보기',discuss:'이 작품 상담하기',details:'작품 정보',origin:'다이아몬드 종류 선택',note:'연출 이미지는 작품의 분위기를 보여줍니다. 사양과 시작 가격은 대략적인 안내이며, 최종 조건은 선택하신 다이아몬드와 사양에 따라 개별적으로 확정됩니다.',moreDescriptions:['물방울 모양 다이아몬드가 옐로 골드를 따라 흐르듯 이어지는 브레이슬릿.','래디언트 컷 중심석을 다이아몬드 헤일로가 감싸는 링.','라운드 중심석을 다이아몬드 헤일로가 감싸는 링.']}};
function productRecord(n){const si=collectionIndex.signature.indexOf(n);if(si>=0){const [name,type,description]=signatures[lang].items[si];return {name,type,description,spec:catalogSpecs.signature[si],n}}const ci=collectionIndex.more.indexOf(n);if(ci>=0)return {name:copy[lang].productNames[ci],type:copy[lang].productTypes[ci],description:productPageCopy[lang].moreDescriptions[ci],spec:catalogSpecs.concept[ci],n};return null}
